draw:
// Five arrangements of the same mass M at the same outer radius R.
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "middle";

var names = ["Hoop", "Disk", "Shell", "Solid sphere", "Rod (length L)"];
var coefs = [1.0, 0.5, 2 / 3, 0.4, 1 / 12];
var labels = ["M R^2", "0.5 M R^2", "0.67 M R^2", "0.40 M R^2", "0.083 M L^2"];

var rows = 5;
var top = H * 0.10;
var rowH = (H * 0.86 - top) / rows;
var iconX = W * 0.10;
var iconR = Math.min(rowH * 0.34, W * 0.055);
var barX0 = W * 0.42;
var barMax = W * 0.30;

ctx.fillStyle = C.ink;
ctx.fillText("shape", W * 0.02, top - rowH * 0.42);
ctx.fillText("I / M R^2  (bar)", barX0, top - rowH * 0.42);

for (var i = 0; i < rows; i++) {
  var cy = top + rowH * (i + 0.5);

  // icon
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1;
  if (i === 0) {
    ctx.strokeStyle = C.figure;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(iconX, cy, iconR, 0, Math.PI * 2);
    ctx.stroke();
  } else if (i === 1) {
    ctx.fillStyle = C.figure;
    ctx.beginPath();
    ctx.arc(iconX, cy, iconR, 0, Math.PI * 2);
    ctx.fill();
  } else if (i === 2) {
    ctx.strokeStyle = C.figure;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(iconX, cy, iconR, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = C.rule;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(iconX, cy, iconR * 0.4, iconR, 0, 0, Math.PI * 2);
    ctx.stroke();
  } else if (i === 3) {
    ctx.fillStyle = C.figure;
    ctx.beginPath();
    ctx.arc(iconX, cy, iconR, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = C.paper;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(iconX, cy, iconR * 0.4, iconR, 0, 0, Math.PI * 2);
    ctx.stroke();
  } else {
    ctx.strokeStyle = C.figure;
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(iconX - iconR, cy);
    ctx.lineTo(iconX + iconR, cy);
    ctx.stroke();
  }

  // axis through the centre of every icon
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath();
  ctx.moveTo(iconX, cy - iconR * 1.5);
  ctx.lineTo(iconX, cy + iconR * 1.5);
  ctx.stroke();
  ctx.setLineDash([]);

  // name
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(names[i], W * 0.19, cy);

  // bar
  ctx.fillStyle = C.faint;
  ctx.fillRect(barX0, cy - rowH * 0.18, barMax, rowH * 0.36);
  ctx.fillStyle = C.accent;
  ctx.fillRect(barX0, cy - rowH * 0.18, barMax * coefs[i], rowH * 0.36);
  ctx.fillStyle = C.ink;
  ctx.fillText(labels[i], barX0 + barMax + W * 0.02, cy);
}

// the k = 1 ceiling
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(barX0 + barMax, top - rowH * 0.2);
ctx.lineTo(barX0 + barMax, H * 0.88);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("k = 1: all mass at the rim", barX0 + barMax * 0.5, H * 0.95);

// Uniform rod, mass M, length L, pivoted a distance d from its centre.
var g = 9.8;
var L = p.L;
var M = p.M;
var d = p.d;
var Icm = M * L * L / 12;
var I = Icm + M * d * d;

// period of small oscillations; d = 0 is a free axis, no restoring torque
var hasSwing = d > 0.005;
var T = hasSwing ? 2 * Math.PI * Math.sqrt(I / (M * g * d)) : 0;
var theta0 = 0.28;
var theta = hasSwing ? theta0 * Math.cos(2 * Math.PI * t / T) : 0;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

// ---- left panel: the swinging rod ----
var px = W * 0.26;
var py = H * 0.16;
var sc = (H * 0.62) / 1.7;

// ceiling
ctx.strokeStyle = C.faint;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(px - W * 0.16, py);
ctx.lineTo(px + W * 0.16, py);
ctx.stroke();

// vertical reference
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px, py + sc * 1.05);
ctx.stroke();
ctx.setLineDash([]);

var ux = Math.sin(theta);
var uy = Math.cos(theta);
var farEnd = L / 2 + d;
var nearEnd = L / 2 - d;

ctx.strokeStyle = C.figure;
ctx.lineWidth = 6;
ctx.lineCap = "round";
ctx.beginPath();
ctx.moveTo(px - ux * nearEnd * sc, py - uy * nearEnd * sc);
ctx.lineTo(px + ux * farEnd * sc, py + uy * farEnd * sc);
ctx.stroke();
ctx.lineCap = "butt";

// centre of mass marker
var cmx = px + ux * d * sc;
var cmy = py + uy * d * sc;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cmx, cmy, 5, 0, Math.PI * 2);
ctx.fill();

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(px, py, 4, 0, Math.PI * 2);
ctx.fill();

// d label
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(cmx, cmy);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("d", (px + cmx) / 2 + 7, (py + cmy) / 2);
ctx.fillStyle = C.ink;
ctx.fillText("pivot", px + 8, py - 10);
ctx.fillText("centre of mass", cmx + 9, cmy + 12);

// ---- right panel: T against d ----
var gx0 = W * 0.52;
var gx1 = W * 0.95;
var gy0 = H * 0.14;
var gy1 = H * 0.82;
var dmax = L / 2;
var Tmax = 2 * Math.PI * Math.sqrt((Icm + M * dmax * dmax) / (M * g * dmax)) * 1.9;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, gy0);
ctx.lineTo(gx0, gy1);
ctx.lineTo(gx1, gy1);
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
var started = false;
var dBest = L / Math.sqrt(12);
for (var i = 0; i <= 160; i++) {
  var dd = dmax * (i / 160);
  if (dd < 0.02) { continue; }
  var TT = 2 * Math.PI * Math.sqrt((Icm + M * dd * dd) / (M * g * dd));
  var X = gx0 + (gx1 - gx0) * (dd / dmax);
  var Y = gy1 - (gy1 - gy0) * Math.min(TT / Tmax, 1);
  if (!started) { ctx.moveTo(X, Y); started = true; } else { ctx.lineTo(X, Y); }
}
ctx.stroke();

// marker for the minimum
if (dBest <= dmax) {
  var Tb = 2 * Math.PI * Math.sqrt((Icm + M * dBest * dBest) / (M * g * dBest));
  var bx = gx0 + (gx1 - gx0) * (dBest / dmax);
  var by = gy1 - (gy1 - gy0) * Math.min(Tb / Tmax, 1);
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 4]);
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.lineTo(bx, gy1);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText("d = L/sqrt(12)", bx, gy1 + 14);
}

// current point
if (hasSwing) {
  var cx = gx0 + (gx1 - gx0) * (d / dmax);
  var cy = gy1 - (gy1 - gy0) * Math.min(T / Tmax, 1);
  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.arc(cx, cy, 4.5, 0, Math.PI * 2);
  ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("period T", gx0 + 4, gy0 - 2);
ctx.textAlign = "right";
ctx.fillText("d", gx1, gy1 + 14);

out.note = hasSwing
  ? "I = " + I.toFixed(4) + " kg m^2   (I_cm = " + Icm.toFixed(4) +
    ", M d^2 = " + (M * d * d).toFixed(4) + ")   T = " + T.toFixed(3) + " s"
  : "I = " + Icm.toFixed(4) + " kg m^2, the smallest possible. No gravity lever arm, so it does not swing.";

// Disk of mass M and radius R with a circular hole of radius a, centre c from the axis.
var R = 0.30;
var M = 9.0;
var a = p.a;
var c = Math.min(p.c, R - a);

var Ifull = 0.5 * M * R * R;
var mHole = M * (a * a) / (R * R);
var Ihole = 0.5 * mHole * a * a + mHole * c * c;
var Inet = Ifull - Ihole;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var cx = W * 0.30;
var cy = H * 0.50;
var sc = Math.min(H * 0.36, W * 0.24) / R;

// the disk
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, R * sc, 0, Math.PI * 2);
ctx.fill();

// the hole
ctx.fillStyle = C.paper;
ctx.beginPath();
ctx.arc(cx + c * sc, cy, a * sc, 0, Math.PI * 2);
ctx.fill();
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(cx + c * sc, cy, a * sc, 0, Math.PI * 2);
ctx.stroke();

// axis
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(cx, cy - R * sc - 14);
ctx.lineTo(cx, cy + R * sc + 14);
ctx.stroke();
ctx.setLineDash([]);

// offset arrow
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + c * sc, cy);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx + c * sc, cy, 3, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("axis", cx, cy - R * sc - 24);
ctx.fillText("c = " + c.toFixed(2) + " m", cx + c * sc * 0.5, cy - 12);
ctx.fillText("hole radius a = " + a.toFixed(2) + " m", cx, cy + R * sc + 26);

// ---- the bookkeeping, drawn as three bars ----
var bx = W * 0.56;
var bw = W * 0.34;
var rowY = [H * 0.26, H * 0.48, H * 0.70];
var vals = [Ifull, Ihole, Inet];
var tags = ["full disk", "piece removed", "what is left"];
var scaleBar = bw / Ifull;

for (var i = 0; i < 3; i++) {
  ctx.fillStyle = C.faint;
  ctx.fillRect(bx, rowY[i] - 9, bw, 18);
  ctx.fillStyle = i === 1 ? C.rule : C.accent;
  ctx.fillRect(bx, rowY[i] - 9, Math.max(vals[i] * scaleBar, 1), 18);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(tags[i], bx, rowY[i] - 22);
  ctx.textAlign = "right";
  ctx.fillText(vals[i].toFixed(4), bx + bw, rowY[i] - 22);
}

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("I about the central axis (kg m^2)", bx, H * 0.10);

out.note = "m_hole = " + mHole.toFixed(3) + " kg,  I_hole = 0.5 m a^2 + m c^2 = " +
  (0.5 * mHole * a * a).toFixed(4) + " + " + (mHole * c * c).toFixed(4) +
  " = " + Ihole.toFixed(4) + ",  I = " + Ifull.toFixed(4) + " - " + Ihole.toFixed(4) +
  " = " + Inet.toFixed(4) + " kg m^2";
